/// Vite 静态资源类型声明（SVG / TTF / WOFF2 导入）
declare module '*.svg' {
  const src: string
  export default src
}
declare module '*.ttf' {
  const src: string
  export default src
}
declare module '*.woff2' {
  const src: string
  export default src
}
declare module '*.png' {
  const src: string
  export default src
}
